mapper.update:
UPDATE consultation_logs
session_id = #{sessionId}, user_id = #{userId}, agent_id = #{agentId}, user_input = #{userInput}, ai_response = #{aiResponse}, dify_conversation_id = #{difyConversationId}, intent = #{intent}, channel = #{channel}, duration = #{duration}, satisfaction = #{satisfaction},
WHERE id = #{id}

mapper.select:
SELECT AVG(satisfaction) FROM consultation_logs
WHERE agent_id = #{agentId} AND satisfaction IS NOT NULL
AND create_time BETWEEN #{start} AND #{end}

SELECT AVG(satisfaction) FROM consultation_logs
WHERE satisfaction IS NOT NULL
AND create_time BETWEEN #{start} AND #{end}

SELECT satisfaction AS satisfactionLevel, COUNT(*) AS totalCount
FROM consultation_logs WHERE agent_id = #{agentId}
AND satisfaction IS NOT NULL AND create_time BETWEEN #{start} AND #{end}
GROUP BY satisfaction

SELECT DATE(create_time) AS statDate, COUNT(DISTINCT session_id) AS totalCount
FROM consultation_logs WHERE agent_id = #{agentId}
AND create_time BETWEEN #{start} AND #{end}
GROUP BY DATE(create_time) ORDER BY statDate

SELECT COUNT(DISTINCT agent_id) FROM consultation_logs
WHERE agent_id IS NOT NULL
AND create_time BETWEEN #{start} AND #{end}
